import * as React from "react"
import { Link } from "gatsby"

const Layout = ({ location, title, children }) => {
  const rootPath = `${__PATH_PREFIX__}/`
  const isRootPath = location.pathname === rootPath
  let header

  if (isRootPath) {
    header = (
      <h1 className="main-heading">
        <Link to="/">{title}</Link>
      </h1>
    )
  } else {
    header = (
      <Link className="header-link-home" to="/">
        {title}
      </Link>
    )
  }

  return (
    <div className="global-wrapper" data-is-root-path={isRootPath}>
      <header className="global-header">{header}</header>
      <main>{children}</main>
      <footer style={{ backgroundColor: "#f3f4f6", padding: "1.5rem 1rem", marginTop: "2rem" }}>
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            alignItems: "center",
            gap: "1rem",
            maxWidth: "768px",
            margin: "0 auto",
          }}
        >
          <img
            src="/static/5539e50aa5835cfa1da1f7d93397820c/d24ee/profile-pic.jpg"
            srcSet="/static/5539e50aa5835cfa1da1f7d93397820c/d24ee/profile-pic.jpg 1x,
                    /static/5539e50aa5835cfa1da1f7d93397820c/64618/profile-pic.jpg 2x"
            alt="Profile picture"
            style={{
              width: "50px",
              height: "50px",
              objectFit: "cover",
              borderRadius: "9999px",
            }}
            loading="lazy"
          />
          <p style={{ fontSize: "0.875rem", lineHeight: "1.5" }}>
            Ditulis oleh <strong>Dery Pra Tivi</strong>. Blog ini mungkin bukan yang kamu harapkan.
            Kalau kamu lagi cari cara buat nyolong Wi-Fi tetangga, saya sarankan cari tempat lain.{" "}
            <a
              href="https://twitter.com/deretxt"
              style={{ color: "#1d4ed8", textDecoration: "underline" }}
              target="_blank"
              rel="noopener noreferrer"
            >
              Kamu bisa follow saya di Twitter
            </a>.
          </p>
        </div>
      </footer>
    </div>
  )
}

export default Layout
